/**
 * 输出 JS 图标助手脚本
 * 注入 window.EE_ICONS 数据与 window.eeIcon(name, extraClass) 函数，
 * 供 JS 动态生成的图标使用，返回的 SVG HTML 与 PHP 端 icon() 一致
 * @return string <script> 标签字符串
 */
function icon_sprite(): string {
    $icons = $GLOBALS['EE_ICONS'] ?? [];
    $json = json_encode($icons, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    return '<script>window.EE_ICONS=' . $json . ';window.eeIcon=function(n,c){var d=window.EE_ICONS[n]||"<circle cx=\"12\" cy=\"12\" r=\"10\"/>";return "<svg class=\"icon"+(c?" "+c:"")+"\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">"+d+"</svg>";};</script>';
}

/**
 * 返回内联 SVG 图标标记（PHP 端使用）
 * @param string $name 图标名
 * @param string $extra_class 额外 class（如 me-1、icon-spin）
 */
function icon(string $name, string $extra_class = ''): string {
    $icons = $GLOBALS['EE_ICONS'] ?? [];
    if (!isset($icons[$name])) {
        // Fallback: return a simple circle if icon not found
        return '<svg class="icon' . ($extra_class ? ' ' . $extra_class : '') . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/></svg>';
    }
    return '<svg class="icon' . ($extra_class ? ' ' . $extra_class : '') . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' . $icons[$name] . '</svg>';
}
